   250|export async function getSchedulerState(): Promise<SchedulerState> {
   251|  // Durable (Supabase) when configured so run history survives restarts/deploys
   252|  // on the ephemeral-disk Render tier; falls back to the local filesystem otherwise.
   253|  if (isDurableStoreConfigured()) {
   254|    try {
   255|      const parsed = await readDurableJson<unknown>(STATE_PATH, null);
   256|      if (parsed) return normalizeState(parsed);
   257|      return freshSchedulerState();
   258|    } catch {
   259|      return freshSchedulerState();
   260|    }
   261|  }
   262|  try {
   263|    const raw = await readFile(STATE_PATH, 'utf8');
   264|    return normalizeState(JSON.parse(raw));
   265|  } catch {
   266|    return freshSchedulerState();
   267|  }
