   270|async function writeSchedulerState(state: SchedulerState): Promise<void> {
   271|  const next: SchedulerState = { ...state, updatedAt: nowIso() };
   272|  if (isDurableStoreConfigured()) {
   273|    await writeDurableJson(STATE_PATH, next);
   274|    return;
   275|  }
   276|  await ensureDir();
   277|  await writeFile(TMP_PATH, JSON.stringify(next, null, 2), 'utf8');
   278|  await rename(TMP_PATH, STATE_PATH);
