   949|/**
   950| * Run a single scheduled job NOW (regardless of due time) and persist its
   951| * result + next-due. Concurrency-guarded per kind. Never throws.
   952| */
   953|export async function runScheduledJob(
   954|  kind: ScheduledJobKind,
   955|  deps: { selfAudit?: SelfAuditDeps; drift?: DriftDeps } = {},
   956|): Promise<ScheduledJobResult> {
   957|  if (inFlight.has(kind)) {
   958|    return { kind, ok: false, durationMs: 0, summary: 'Already running.', error: 'Job already in flight.' };
   959|  }
   960|  inFlight.add(kind);
   961|  const startedAt = nowIso();
   962|  const start = Date.now();
   963|  let engineResult: { discovered?: number; savedToCrm?: number; duplicatesSkipped?: number; outreachQueued?: number; sendingEnabled?: boolean; source?: string; evidence?: string[]; engine?: string } | null = null;
   964|  try {
   965|    const result =
   966|      kind === 'daily_self_audit'
   967|        ? await runSelfAuditJob(deps.selfAudit)
   968|        : kind === 'daily_executive_report'
   969|          ? await runDailyReportJob()
   970|          : kind === 'daily_drift_detection'
   971|            ? await runDriftJob(deps.drift)
   972|          : kind === 'daily_technology_ideas'
   973|            ? await runTechnologyIdeasJob()
   974|            : kind === 'daily_deploy_monitor'
   975|              ? await runDeployMonitorJob()
   976|              : kind === 'daily_enterprise_os'
   977|                ? await runEnterpriseOsSnapshotJob()
   978|                : await runExecutionEngineJob(kind);
   979|
   980|    // Capture the engine result details for the permanent run record.
   981|    if (isExecutionEngineKind(kind)) {
   982|      try {
   983|        engineResult = await captureEngineResult(kind);
   984|      } catch {
   985|        engineResult = null;
   986|      }
   987|    }
   988|
   989|    // HONEST STATUS CLASSIFICATION (ITEM 11): A Postgres statement timeout
   990|    // on a late CRM write does NOT mean the run failed — the engine may have
   991|    // already discovered and inserted hundreds of real SEC records. Classify
   992|    // based on whether real work was done, not just whether the outer catch fired.
   993|    const honestStatus = classifyRunStatus(result, engineResult);
   994|    const isRealFailure = honestStatus === 'failed';
   995|    await patchJobState(kind, (job, now) => ({
   996|      ...job,
   997|      lastRunAt: nowIso(now),
   998|      nextDueAt: computeNextDue(now, job.intervalMs),
   999|      lastStatus: honestStatus,
  1000|      lastDurationMs: result.durationMs,
  1001|      lastSummary: result.error && isRealFailure ? `${result.summary} (${result.error})` : result.summary,
  1002|      runCount: job.runCount + 1,
  1003|      failureCount: job.failureCount + (isRealFailure ? 1 : 0),
  1004|    }));
  1005|    await appendRunLog({ type: 'job_run', kind, ok: result.ok, durationMs: result.durationMs, summary: result.summary, at: nowIso() });
  1006|
  1007|    // PERMANENT per-run evidence record (2026-07-26) — one row per execution,
  1008|    // persisted to the durable Supabase store. Survives restarts/deploys.
  1009|    try {
  1010|      const { recordAutonomousRun } = await import('./ivx-autonomous-run-log');
  1011|      await recordAutonomousRun({
  1012|        kind: kind as ScheduledJobKind,
  1013|        engine: engineKindToName(kind),
  1014|        workerId: WORKER_FOR_KIND[kind] ?? 'W8',
  1015|        startedAt,
  1016|        durationMs: Date.now() - start,
  1017|        status: honestStatus,
  1018|        summary: result.summary,
  1019|        error: result.error ?? null,
  1020|        recordsDiscovered: engineResult?.discovered ?? 0,
  1021|        recordsInserted: engineResult?.savedToCrm ?? 0,
  1022|        recordsUpdated: 0,
  1023|        duplicatesSkipped: engineResult?.duplicatesSkipped ?? 0,
  1024|        outreachQueued: engineResult?.outreachQueued ?? 0,
  1025|        sendingEnabled: engineResult?.sendingEnabled ?? false,
  1026|        source: engineResult?.source ?? 'IVX Autonomous Scheduler',
  1027|        evidence: engineResult?.evidence ?? [],
  1028|      });
  1029|    } catch {
  1030|      // run-log persistence is best-effort; never break the scheduler.
  1031|    }
  1032|
  1033|    return result;
  1034|  } finally {
  1035|    inFlight.delete(kind);
  1036|  }
  1037|}
