   807|async function runTests(testCommands: string[]): Promise<TestRunResults> {
   808|  let typecheckResult: 'pass' | 'fail' | 'skipped' = 'skipped';
   809|  let testResult: 'pass' | 'fail' | 'skipped' = 'skipped';
   810|  let typecheckOutput = '';
   811|  let testOutput = '';
   812|
   813|  // Run tsc typecheck
   814|  try {
   815|    const { stdout, stderr, code } = await execFileAsync('bun', ['x', 'tsc', '--noEmit'], 120_000);
   816|    typecheckOutput = (stdout + stderr).slice(-2000);
   817|    typecheckResult = code === 0 ? 'pass' : 'fail';
   818|  } catch (err) {
   819|    typecheckOutput = err instanceof Error ? err.message.slice(-2000) : String(err);
   820|    typecheckResult = 'fail';
   821|  }
   822|
   823|  // Run tests (use the specified commands or default to `bun test`)
   824|  const testCmds = testCommands.length > 0 ? testCommands : ['bun test'];
   825|  for (const cmd of testCmds) {
   826|    if (!cmd.includes('bun test') && !cmd.includes('tsc')) continue;
   827|    try {
   828|      const parts = cmd.split(/\s+/);
   829|      const { stdout, stderr, code } = await execFileAsync(parts[0] ?? 'bun', parts.slice(1), 180_000);
   830|      testOutput += (stdout + stderr).slice(-3000);
   831|      testResult = code === 0 ? 'pass' : 'fail';
   832|      if (code !== 0) break;
   833|    } catch (err) {
   834|      testOutput += err instanceof Error ? err.message.slice(-2000) : String(err);
   835|      testResult = 'fail';
   836|      break;
   837|    }
   838|  }
   839|
   840|  const passed = typecheckResult !== 'fail' && testResult !== 'fail';
   841|  const summary = `typecheck=${typecheckResult} tests=${testResult}`;
   842|  return { passed, typecheck: typecheckResult, tests: testResult, typecheckOutput, testOutput, summary };
